// ─── Article card ─────────────────────────────────────────────────────────────
function ArticleCard({ article, onClick }){
  const cat = CATS.find(c=>c.id===article.category);
  const preview = article.body.substring(0,155) + "…";
  const hasVideo = article.videoUrl;
  return (
    <div className="card card-hover" style={{cursor:"pointer",display:"flex",flexDirection:"column"}} onClick={()=>onClick(article)}>
      {hasVideo && (
        <div className="video-wrap" onClick={e=>e.stopPropagation()}>
          <iframe src={article.videoUrl} title={article.videoCaption||"Video"} allow="accelerometer;autoplay;clipboard-write;encrypted-media;gyroscope;picture-in-picture" allowFullScreen/>
        </div>
      )}
      {!hasVideo && article.imageDataUrl && (
        <img src={article.imageDataUrl} alt="Article" className="article-image"/>
      )}
      <span className={`badge ${cat?.badge}`} style={{marginBottom:10,display:"inline-block"}}>{cat?.label}</span>
      <h3 className="serif" style={{fontSize:18,lineHeight:1.35,marginBottom:8,flex:1}}>{article.title}</h3>
      <p style={{fontSize:13,color:C.muted,lineHeight:1.6}}>{preview}</p>
      <div style={{marginTop:14,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <span style={{fontSize:12,color:C.muted}}>{article.authorName} · {article.submittedAt}</span>
        <span style={{fontSize:13,color:C.teal600,fontWeight:600}}>Read →</span>
      </div>
    </div>
  );
}

function ArticleModal({ article, onClose }){
  const cat = CATS.find(c=>c.id===article.category);
  const paras = article.body.split("\n").filter(Boolean);
  return (
    <div className="modal-overlay" onClick={onClose}>
      <div style={{background:"#fff",borderRadius:22,padding:"2rem",maxWidth:700,width:"94%",maxHeight:"88vh",overflowY:"auto",boxShadow:"0 24px 80px rgba(13,59,48,0.2)"}} onClick={e=>e.stopPropagation()}>
        <button onClick={onClose} style={{float:"right",background:"none",border:"none",fontSize:22,color:C.muted,cursor:"pointer",lineHeight:1}}>✕</button>
        <span className={`badge ${cat?.badge}`} style={{marginBottom:14,display:"inline-block"}}>{cat?.label}</span>
        <h2 className="serif" style={{fontSize:26,lineHeight:1.3,marginBottom:8}}>{article.title}</h2>
        <p style={{fontSize:13,color:C.muted,marginBottom:20}}>By {article.authorName} · {article.submittedAt}</p>
        {article.videoUrl && (
          <div style={{marginBottom:20}}>
            <div className="video-wrap"><iframe src={article.videoUrl} title="video" allow="accelerometer;autoplay;clipboard-write;encrypted-media;gyroscope;picture-in-picture" allowFullScreen/></div>
            {article.videoCaption && <p style={{fontSize:12,color:C.muted,textAlign:"center",marginTop:6}}>{article.videoCaption}</p>}
          </div>
        )}
        {!article.videoUrl && article.imageDataUrl && (
          <img src={article.imageDataUrl} alt="Article" style={{width:"100%",borderRadius:14,objectFit:"cover",maxHeight:300,marginBottom:20}}/>
        )}
        <div style={{borderTop:`1px solid ${C.border}`,paddingTop:20}}>
          {paras.map((p,i)=><p key={i} style={{fontSize:16,lineHeight:1.85,marginBottom:18,color:C.charcoal}}>{p}</p>)}
        </div>
      </div>
    </div>
  );
}

