// ─── App root ─────────────────────────────────────────────────────────────────
export default function App(){
  const [view, setView] = useState("home");
  const [articles, setArticles] = useState([]);
  useEffect(() => {
    async function load() {
      const { data, error } = await supabase.from('articles').select('*');
      if (error) {
        console.error('Supabase load error:', error);
        setArticles(INIT_ARTICLES);
        return;
      }
      if (data && data.length > 0) {
        setArticles(data.map(row => row.data));
      } else {
        const seed = INIT_ARTICLES.map(a => ({ id: String(a.id), data: a }));
        await supabase.from('articles').upsert(seed);
        setArticles(INIT_ARTICLES);
      }
    }
    load();

    const channel = supabase
      .channel('articles')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'articles' }, payload => {
        if (payload.eventType === 'INSERT') {
          setArticles(prev => prev.some(a => String(a.id) === String(payload.new.id)) ? prev : [...prev, payload.new.data]);
        } else if (payload.eventType === 'UPDATE') {
          setArticles(prev => prev.map(a => String(a.id) === String(payload.new.id) ? payload.new.data : a));
        } else if (payload.eventType === 'DELETE') {
          setArticles(prev => prev.filter(a => String(a.id) !== String(payload.old.id)));
        }
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, []);

  const [users, setUsers] = useState(() => {
    try {
      const saved = localStorage.getItem("sss_users");
      return saved ? JSON.parse(saved) : INIT_USERS;
    } catch { return INIT_USERS; }
  });
  useEffect(() => {
    try { localStorage.setItem("sss_articles", JSON.stringify(articles)); } catch {}
  }, [articles]);

  useEffect(() => {
    try { localStorage.setItem("sss_users", JSON.stringify(users)); } catch {}
  }, [users]);
  const [currentUser, setCurrentUser] = useState(null);
  const [readArticle, setReadArticle] = useState(null);

  function safeSetView(v){
    if (v==="dashboard"&&!currentUser){setView("auth");return;}
    if (v==="admin"&&currentUser?.role!=="Admin"){setView("home");return;}
    setView(v);
  }

  return (
    <>
      <style>{CSS}</style>
      <div style={{minHeight:"100vh",display:"flex",flexDirection:"column"}}>
        <CrisisBar/>
        <Header view={view} setView={safeSetView} currentUser={currentUser} setCurrentUser={setCurrentUser}/>
        <main style={{flex:1}}>
          {view==="home"&&<HomeView articles={articles} setView={safeSetView} onRead={setReadArticle}/>}
          {(view==="reality-check"||view==="mind-mechanics"||view==="toolkit")&&<CategoryView category={view} articles={articles} onRead={setReadArticle}/>}
          {view==="talk"&&<TalkPage/>}
          {view==="auth"&&<AuthView users={users} setUsers={setUsers} setCurrentUser={setCurrentUser} setView={safeSetView}/>}
          {view==="dashboard"&&currentUser&&<DashboardView currentUser={currentUser} articles={articles} setArticles={setArticles}/>}
          {view==="admin"&&currentUser?.role==="Admin"&&<AdminView articles={articles} setArticles={setArticles}/>}
        </main>
        <Footer setView={safeSetView}/>
        {readArticle&&<ArticleModal article={readArticle} onClose={()=>setReadArticle(null)}/>}
      </div>
    </>
  );
}
